import{_ as t,o,c as a,a5 as l}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Server Example: Cloth on a Slope","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/cloth_on_slope.md","filePath":"sections/examples/server/cloth_on_slope.md"}'),r={name:"sections/examples/server/cloth_on_slope.md"};function s(h,e,i,n,d,c){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="server-example-cloth-on-a-slope" tabindex="-1">Server Example: Cloth on a Slope <a class="header-anchor" href="#server-example-cloth-on-a-slope" aria-label="Permalink to &quot;Server Example: Cloth on a Slope&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A 1 kg box stands on a cloth on each of two ramps, with a friction coefficient of 0.5 everywhere. The ground holds the cloth under the box with the friction of the box&#39;s weight, so on the 18 degree ramp, below the friction angle (tan 18° = 0.32 &lt; 0.5), the cloth and the box stay where they landed. On the 30 degree ramp (tan 30° = 0.58) they slide down together. The cloth is solved together with the box and the ramps (<a href="./../../DeformableObject.html#solving-deformables-together-with-the-bodies"><code>World::setMonolithicDeformables()</code></a>). Every four seconds the world starts over, and the example prints how far each box moved between 0.5 s and 1.5 s.</p><table tabindex="0"><thead><tr><th>Ramp</th><th>Default coupling</th><th>Solved together</th></tr></thead><tbody><tr><td>18 degrees: box travel</td><td>74 mm</td><td>0.001 mm</td></tr><tr><td>30 degrees: box travel (Coulomb friction: 0.66 m)</td><td>1.26 m</td><td>1.12 m</td></tr></tbody></table><p>In the default coupling the ground holds each particle with the friction of its own weight only, so the box drags the cloth down the gentle ramp.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>cloth_on_slope</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/cloth_on_slope</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/cloth_on_slope.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The ramps are static boxes tilted about the y axis; each cloth is a 0.48 m square of 25 x 25 particles weighing 0.15 kg, laid on the upper part of its ramp, with the box on its middle.</li><li>On the steep ramp the box and the cloth slide faster than Coulomb friction allows; see the known limitations in <a href="./../../DeformableObject.html#solving-deformables-together-with-the-bodies">Deformable Objects</a>.</li><li>The scene lives in <code>include/cloth_on_slope.hpp</code>.</li></ul>',12)])])}const b=t(r,[["render",s]]);export{m as __pageData,b as default};
